def pre_suggestion_anchor_owner(source):
    from suggestion_menu_prepare_scope_contract import pre_suggestion_menu_prepare
    source = pre_suggestion_menu_prepare(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_anchor_owner_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_anchor_owner(data.decode()).encode() if path.suffix == '.swift' else data

